// Explanation helper: use a translated field when one exists.
// Until a lesson has a translation for the selected language, keep its
// original Hindi explanation visible instead of showing a blank explanation.
function getLessonExplanation(step, language) {
  if (language === "hi") return step.hi || "";
  return step[language] || step.hi || "";
}
